<?php
require_once __DIR__ . '/config.php';require_login();$pdo=db();
$from=trim((string)($_GET['from']??''));$to=trim((string)($_GET['to']??''));$type=(string)($_GET['type']??'');$q=trim((string)($_GET['q']??''));
$where=[];$params=[];if($from!==''&&preg_match('/^\d{4}-\d{2}-\d{2}$/',$from)){$where[]='DATE(t.created_at)>=?';$params[]=$from;}if($to!==''&&preg_match('/^\d{4}-\d{2}-\d{2}$/',$to)){$where[]='DATE(t.created_at)<=?';$params[]=$to;}if(in_array($type,['in','out','adjustment'],true)){$where[]='t.type=?';$params[]=$type;}if($q!==''){$where[]='(p.name LIKE ? OR p.sku LIKE ? OR u.name LIKE ?)';array_push($params,"%$q%","%$q%","%$q%");}$clause=$where?' WHERE '.implode(' AND ',$where):'';
$sql="SELECT t.*,p.name product_name,p.sku,u.name user_name FROM stock_transactions t JOIN products p ON p.id=t.product_id JOIN users u ON u.id=t.user_id$clause ORDER BY t.created_at DESC,t.id DESC";
if(isset($_GET['export'])){$s=$pdo->prepare($sql);$s->execute($params);$rows=$s->fetchAll();header('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename="laporan-inventori.csv"');$out=fopen('php://output','w');fwrite($out,"\xEF\xBB\xBF");fputcsv($out,['ID','Waktu','SKU','Produk','Jenis','Jumlah','Petugas','Catatan']);foreach($rows as $r)fputcsv($out,[$r['id'],$r['created_at'],$r['sku'],$r['product_name'],$r['type'],$r['quantity'],$r['user_name'],$r['note']]);fclose($out);exit;}
$s=$pdo->prepare("SELECT COUNT(*) FROM stock_transactions t JOIN products p ON p.id=t.product_id JOIN users u ON u.id=t.user_id$clause");$s->execute($params);$total=(int)$s->fetchColumn();$per=15;$pages=max(1,(int)ceil($total/$per));$page=max(1,min($pages,(int)($_GET['page']??1)));$s=$pdo->prepare($sql." LIMIT $per OFFSET ".(($page-1)*$per));$s->execute($params);$rows=$s->fetchAll();$pageTitle='Histori & laporan';require 'partials_header.php';?>
<section class="panel"><div class="panel-heading"><h2>Filter histori transaksi</h2></div><form method="get" class="filters"><input type="date" name="from" value="<?= e($from) ?>" aria-label="Tanggal mulai"><input type="date" name="to" value="<?= e($to) ?>" aria-label="Tanggal akhir"><select name="type"><option value="">Semua jenis</option><option value="in" <?= $type==='in'?'selected':'' ?>>Barang masuk</option><option value="out" <?= $type==='out'?'selected':'' ?>>Barang keluar</option></select><input name="q" placeholder="Cari produk, SKU, petugas" value="<?= e($q) ?>"><button class="btn primary">Filter</button><a class="btn" href="history.php">Reset</a><button class="btn" name="export" value="1">Ekspor CSV</button></form></section>
<section class="panel"><div class="panel-heading"><h2>Riwayat transaksi <span class="muted">(<?= $total ?>)</span></h2></div><div class="table-wrap"><table><thead><tr><th>Waktu</th><th>Produk</th><th>Jenis</th><th>Jumlah</th><th>Petugas</th><th>Catatan</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?= e($r['created_at']) ?></td><td><strong><?= e($r['product_name']) ?></strong><small><?= e($r['sku']) ?></small></td><td><span class="badge <?= e($r['type']) ?>"><?= e($r['type']) ?></span></td><td><?= (int)$r['quantity'] ?></td><td><?= e($r['user_name']) ?></td><td><?= e($r['note']) ?></td></tr><?php endforeach; ?><?php if(!$rows): ?><tr><td colspan="6" class="empty">Tidak ada histori yang sesuai filter.</td></tr><?php endif; ?></tbody></table></div><div class="pagination"><span>Halaman <?= $page ?> dari <?= $pages ?></span><div><?php if($page>1): ?><a href="?<?= http_build_query(array_merge($_GET,['page'=>$page-1])) ?>">← Sebelumnya</a><?php endif; ?> <?php if($page<$pages): ?><a href="?<?= http_build_query(array_merge($_GET,['page'=>$page+1])) ?>">Berikutnya →</a><?php endif; ?></div></div></section><?php require 'partials_footer.php'; ?>
